const lesson=id=>allLessons().find(x=>x.id===id);
const catalogMap=new Map(window.CATALOG.map(x=>[x.word,x]));
try {const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch(e){storageOK=false;}
if(state.active?.ui)taskUI=state.active.ui;
function validate(x){
  if(!x||x.version!==1||typeof x.progress!=='object'||!x.progress||Array.isArray(x.progress)||!Array.isArray(x.custom)||!Array.isArray(x.sessions)||!Array.isArray(x.log))throw Error('不支持的备份格式');
  const d=defaults();const out={...d,...x,settings:{...d.settings,...x.settings}};
  if(out.settings.book==='extra')out.settings.book='all';
  if(!['oral','spelling'].includes(out.settings.mode))out.settings.mode='oral';
  if(out.month){if(typeof out.month!=='object'||!out.month.reviewed||typeof out.month.reviewed!=='object')out.month=null;else {for(const [w,r] of Object.entries(out.month.reviewed))if(!catalogMap.has(w)||!r||![0,1,2].includes(r.rating))delete out.month.reviewed[w];if(out.month.active&&(!Array.isArray(out.month.active.words)||!out.month.active.words.every(w=>catalogMap.has(w))||!Number.isInteger(out.month.active.index)||out.month.active.index<0||out.month.active.index>=out.month.active.words.length))out.month.active=null;}}
  if(![2,4,6].includes(+out.settings.newCount)||![6,12,18].includes(+out.settings.limit)||!Object.hasOwn(bookNames,out.settings.book))out.settings=d.settings;
  out.custom=out.custom.filter(v=>v&&typeof v.id==='string'&&v.id.startsWith('custom-')&&['word','meaning','phrase','phraseZh','sentence','zh','theme','scene','tip','prep'].every(k=>typeof v[k]==='string')&&v.phrase&&v.sentence.includes(v.phrase)).slice(0,10000);
  out.saved=Array.isArray(out.saved)?out.saved.filter(s=>typeof s==='string'):[];
  for(const [id,p] of Object.entries(out.progress)){if(!p||typeof p!=='object'||!Number.isFinite(p.attempts)||!Number.isFinite(p.due)||!Number.isFinite(p.lapses)||!Number.isFinite(p.hits)||!Number.isFinite(p.hints)||!Number.isFinite(p.streak)||!Array.isArray(p.recallDays))delete out.progress[id];}
  out.sessions=out.sessions.filter(s=>s&&typeof s.day==='string'&&Number.isFinite(s.total)&&Number.isFinite(s.independent)&&Number.isFinite(s.hinted)&&Number.isFinite(s.missed)&&Number.isFinite(s.minutes));
  out.log=out.log.filter(l=>l&&typeof l.id==='string'&&typeof l.day==='string'&&Number.isFinite(l.at));
  const ids=new Set([...window.LESSONS,...out.custom].map(l=>l.id));
  if(out.active&&(!Array.isArray(out.active.queue)||!out.active.queue.every(id=>ids.has(id))||!Number.isInteger(out.active.index)||out.active.index<0||out.active.index>=out.active.queue.length||!out.active.stats||!Number.isFinite(out.active.started)))out.active=null;
  if(out.active){const a=out.active;a.learned=a.learned&&typeof a.learned==='object'?a.learned:{};if(['independent','hinted','missed','self'].some(k=>!Number.isFinite(a.stats[k])||a.stats[k]<0))out.active=null;else {a.elapsed=Number.isFinite(a.elapsed)?Math.max(0,a.elapsed):0;a.lastTick=now();if(a.ui&&(![0,1,2].includes(a.ui.hint)||typeof a.ui.input!=='string'||(a.ui.feedback&&typeof a.ui.feedback.correct!=='boolean'&&a.ui.feedback.open!==true)))delete a.ui;}}
  return out;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('当前无法保存进度，请在设置中导出备份。');}}
function persistUI(){if(state.active)state.active.ui={...taskUI};save();}
function touchTimer(){if(!state.active)return;const a=state.active;const delta=now()-(a.lastTick||now());a.elapsed=(a.elapsed||0)+Math.max(0,Math.min(delta,120000));a.lastTick=now();}
let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function inBook(l,b){if(b==='listening'||b==='reading')return l.examSource===b;if(b==='zhenjing')return !!l.bookPage;if(b==='daily')return !['课堂讨论','留学申请','听力替换','阅读改写'].includes(l.scene);if(b==='all')return true;const c=catalogMap.get(l.word.toLowerCase());return b==='common'?!!c?.common:!!c&&!c.common;}
function sourceInfo(l){if(l.examSource)return `<div class="notice book-source">依据《${esc(window.EXAM_SOURCES[l.examSource].title)}》· ${l.sourcePage?'PDF 第 '+l.sourcePage+' 页':'原文表 '+l.sourceTable+'，第 '+l.sourceRow+' 行'}<br>本题改写：<strong>${esc(l.originalSentence)}</strong><br>例句另行编写；词语仅在本题语境中对应，不代表随处可互换。</div>`;return l.bookPage?`<div class="notice book-source">《雅思词汇真经》· ${esc(l.bookChapter)} · 纸书第 ${l.bookPage} 页（PDF 第 ${l.pdfPage} 页）<br>书中搭配：<strong>${esc(l.reference)}</strong><br>本题补全了具体语境，例句另行编写。</div>`:'';}
function pFor(id){return state.progress[id]||{attempts:0,lapses:0,hits:0,hints:0,streak:0,due:0,recallDays:[],self:0};}
function studied(){return Object.entries(state.progress).filter(([,p])=>p.attempts>0);}
function dueLessons(){return allLessons().filter(l=>pFor(l.id).attempts&&pFor(l.id).due<=now());}
function difficult(){return allLessons().filter(l=>{const p=pFor(l.id);return p.attempts&&(p.lapses>0||p.hints>0)&&Math.max(p.streak,p.oralStreak||0)<2;});}
function status(l){const p=pFor(l.id);if(!p.attempts)return '尚未练习';if((p.oralDays||[]).length>=2&&p.oralStreak>=2)return '隔天能说出（自评）';if(p.recallDays.length>=2&&p.streak>=2)return '隔天也能想起';if(p.oralStreak)return '已说出（自评）';if(p.streak)return '本次独立想起';return '还需提示';}
function nav(p){if(page==='practice'){touchTimer();save();}if(p==='practice'&&state.active){state.active.lastTick=now();save();}page=p;render();window.scrollTo({top:0,behavior:'instant'});}
const navItems=[['home','home','开始学习'],['library','book','查词与搭配'],['scenes','grid','场景表达'],['difficult','star','还不会的'],['settings','settings','设置']];
function render(){
 const title=navItems.find(x=>x[0]===page)?.[2]||({practice:'专注练习',month:'单词练习',exams:'听读替换',history:'学习记录',result:'本次练习'}[page]||'学习');
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><svg class="brandmark" viewBox="0 0 36 44" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M18 39V17M18 24C5 24 4 13 5 8c10 0 13 6 13 16ZM18 18C18 5 26 3 32 3c0 10-3 15-14 15ZM8 40h20"/></svg><div><div class="brand-name">词间</div><div class="brand-sub">WORDS TO LIFE</div></div></div><nav class="nav" aria-label="主导航">${navItems.map(([id,i,t])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-note"><div class="sprig">❧</div>慢慢想起，慢慢会用。<br>每天一点，也在向前。</div><div class="sidebar-bottom"><span class="avatar">P</span><div>我的学习空间<br><span class="sub"><i class="online-dot"></i>进度保存在此浏览器</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span class="mobile-brand">词间</span>我的学习空间 <strong>/ ${esc(title)}</strong></div><div class="top-actions"><span>少一点负担，多一点表达</span><button class="icon-btn" data-nav="settings" aria-label="学习设置">${icon('settings')}</button></div></header>${!storageOK?'<div class="storage-alert" role="alert">本地存储暂不可用。当前内容仍可练习，请及时到设置导出备份。</div>':''}<div id="page-content">${({home:home,month:monthPage,library:library,scenes:scenesPage,exams:examsPage,difficult:difficultPage,history:history,settings:settings,practice:practice,result:result}[page]||home)()}</div><footer class="footer"><span>词间 · 把单词用起来</span><span>从眼熟到想起，从单词到表达。</span></footer></main></div>`;
 bind();
}
function intro(en,title,sub,extra=''){return `<section class="intro"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</section>`;}
function home(){const seen=Object.keys(state.month?.reviewed||{}).length;return intro('WORDS TO LIFE','先想起，再用出来。','选一个范围，直接开始。想停时再停。')+`<section class="simple-start"><h2>今天想练哪一部分？</h2><div class="range-choices"><button class="range-choice" data-free-range="all"><strong>全部</strong><span>9389 词</span><b>开始练习 →</b></button><button class="range-choice" data-free-range="common"><strong>常用</strong><span>7956 词</span><b>开始练习 →</b></button></div><p>中文先出现，英文点开才看。选“想起了”或“还不会”，自动下一条。</p>${state.month?.active?'<button class="text-btn" data-nav="month">继续刚才的单词 →</button>':''}${state.active?'<button class="text-btn" data-start="daily">继续刚才的场景 →</button>':''}</section><div class="simple-secondary"><button class="secondary" data-nav="scenes">练场景表达 →</button><button class="text-btn" data-nav="library">查词与搭配</button><button class="text-btn" data-nav="history">学习记录</button><button class="text-btn" data-nav="exams">听读替换资料</button></div><p class="meaning">已覆盖 ${seen} / 9389 词 · 不限每日数量 · 不要求拼写</p>`;}
function sceneCard(s){const [name,en,i]=s;const count=allLessons().filter(l=>l.scene===name).length;return `<button class="scene-card" data-scene="${attr(name)}"><span class="scene-icon">${icon(i)}</span><h3>${esc(name)}</h3><div class="en-label">${en}</div><div class="card-foot"><span>${count} 个搭配 · 可直接练</span>${icon('arrow')}</div></button>`;}
function scenesPage(){const themes=[...new Set(allLessons().map(l=>l.theme))];return intro('IN REAL LIFE','先有想说的话，再学用得上的词。','场景串起表达，主题连接词汇。每次只练一小组。')+situationSection()+`<div class="section-head"><h2>按场景练习</h2><button class="text-btn" data-add="">＋ 添加我想说的话</button></div><div class="topic-grid">${scenes.map(sceneCard).join('')}</div><div class="section-head"><h2>按主题找词</h2><small>同一搭配可以从不同入口找到</small></div><div class="tabs">${themes.map(t=>`<button class="chip" data-theme="${attr(t)}">${esc(t)} · ${allLessons().filter(l=>l.theme===t).length}</button>`).join('')}</div>`;}
function bookOptions(v){return Object.entries(bookNames).map(([k,n])=>`<option value="${k}" ${v===k?'selected':''}>${n}</option>`).join('');}
function switchLibraryTab(tab){lib={tab,book:'all',source:'',theme:'',scene:'',chapter:'',q:'',n:1};render();}
function filteredLibrary(){
 const q=lib.q.toLowerCase().trim();let items;
 if(lib.tab==='all'){const byWord=new Map();for(const l of allLessons()){const key=l.word.toLowerCase();if(!byWord.has(key))byWord.set(key,[]);byWord.get(key).push(l);}items=window.CATALOG.map(c=>({word:c.word,common:c.common,lessons:byWord.get(c.word)||[]}));
  if(lib.book==='common')items=items.filter(c=>c.common);if(lib.book==='daily')items=items.filter(c=>c.lessons.some(l=>inBook(l,'daily')));
  if(lib.book==='listening'||lib.book==='reading')items=items.filter(c=>c.lessons.some(l=>l.examSource===lib.book));if(lib.book==='zhenjing')items=items.filter(c=>c.lessons.some(l=>l.bookPage));if(lib.source)items=items.filter(c=>c.lessons.some(l=>inBook(l,lib.source)));if(lib.chapter)items=items.filter(c=>c.lessons.some(l=>l.bookChapter===lib.chapter));if(lib.theme)items=items.filter(c=>c.lessons.some(l=>l.theme===lib.theme));if(lib.scene)items=items.filter(c=>c.lessons.some(l=>l.scene===lib.scene)||lexical(c.word).scenes.includes(lib.scene));
  if(q)items=items.filter(c=>c.word.includes(q)||lexical(c.word).meaning.toLowerCase().includes(q)||lexical(c.word).phrases.some(p=>p.en.includes(q)||p.zh.includes(q))||c.lessons.some(l=>[l.meaning,l.phraseZh,l.phrase].some(s=>s.toLowerCase().includes(q))));
 }else{items=allLessons().filter(l=>inBook(l,lib.book));if(lib.source)items=items.filter(l=>inBook(l,lib.source));if(lib.tab==='saved')items=items.filter(l=>state.saved.includes(l.id));if(lib.tab==='custom')items=items.filter(l=>l.id.startsWith('custom-'));if(lib.chapter)items=items.filter(l=>l.bookChapter===lib.chapter);if(lib.theme)items=items.filter(l=>l.theme===lib.theme);if(lib.scene)items=items.filter(l=>l.scene===lib.scene);if(q)items=items.filter(l=>[l.word,l.meaning,l.phrase,l.phraseZh,l.zh].some(s=>s.toLowerCase().includes(q)));}
 if(q){const rank=item=>item.word.toLowerCase()===q?0:item.word.toLowerCase().startsWith(q)?1:2;items.sort((a,b)=>rank(a)-rank(b));}
 return items;
}
